<?php
declare(strict_types=1);

function nodenoFurnitureSelection(array $catalog,string $setId,array $components,int $quantity):array {
 $definition=null;foreach($catalog['furnitureSets']??[] as $set)if($set['id']===$setId){$definition=$set;break;}
 if(!$definition||!array_is_list($components)||!$components||count($components)>50||$quantity<1||$quantity>10000)throw new NodenoControlHttpError(422,'set_selection_invalid');
 $allowed=array_fill_keys(array_column($definition['members'],'productId'),true);$products=array_column($catalog['products'],null,'id');$items=[];$seen=[];
 foreach($components as $c){if(!is_array($c)||array_diff(array_keys($c),['productId','quantity'])||!is_string($c['productId']??null)||!isset($allowed[$c['productId']],$products[$c['productId']])||isset($seen[$c['productId']])||!is_int($c['quantity']??null)||$c['quantity']<1||$c['quantity']>99)throw new NodenoControlHttpError(422,'set_component_invalid');$p=$products[$c['productId']];if(($p['hidden']??false)||($p['published']??true)===false)throw new NodenoControlHttpError(422,'product_unavailable');$seen[$p['id']]=true;$items[]=['productId'=>$p['id'],'perSetQuantity'=>$c['quantity'],'quantity'=>$c['quantity']*$quantity];}
 usort($items,static fn($a,$b)=>strcmp((string)$a['productId'],(string)$b['productId']));return ['setId'=>$setId,'name'=>$definition['title'],'quantity'=>$quantity,'items'=>$items];
}
function nodenoWholesaleResolveLines(PDO $db,array $catalog,array $body):array {
 $version=$catalog['meta']['furnitureSetsVersion']??'';if(($body['compositionVersion']??'')!==$version)throw new NodenoControlHttpError(409,'composition_changed');
 $items=$body['items']??[];$sets=$body['sets']??[];if(!is_array($items)||!array_is_list($items)||!is_array($sets)||!array_is_list($sets)||count($items)+count($sets)<1||count($items)+count($sets)>50)throw new NodenoControlHttpError(422,'items_invalid');
 $byId=array_column($catalog['products'],null,'id');$seen=[];$quantities=[];$prepared=[];
 $add=static function(string $id,int $qty)use(&$quantities):void{$quantities[$id]=($quantities[$id]??0)+$qty;if($quantities[$id]>10000000||count($quantities)>50)throw new NodenoControlHttpError(422,'quantity_too_large');};
 foreach($items as $item){if(!is_array($item)||array_diff(array_keys($item),['productId','unit','quantity']))throw new NodenoControlHttpError(422,'item_invalid');$id=$item['productId']??null;$quantity=$item['quantity']??null;if(!is_string($id)||!isset($byId[$id])||isset($seen[$id])||!is_int($quantity)||$quantity<1||$quantity>10000)throw new NodenoControlHttpError(422,'item_invalid');$p=$byId[$id];$unit=$p['saleUnit']??'piece';if(($item['unit']??null)!==$unit)throw new NodenoControlHttpError(422,'sale_unit_invalid');if(($p['hidden']??false)||($p['published']??true)===false)throw new NodenoControlHttpError(422,'product_unavailable');$seen[$id]=true;$add($id,$quantity);$prepared[]=['kind'=>'product','productId'=>$id,'unit'=>$unit,'quantity'=>$quantity];}
 $seenSets=[];
 foreach($sets as $set){if(!is_array($set)||array_diff(array_keys($set),['setId','quantity','components'])||!is_string($set['setId']??null)||!is_int($set['quantity']??null)||!is_array($set['components']??null))throw new NodenoControlHttpError(422,'set_selection_invalid');$resolved=nodenoFurnitureSelection($catalog,$set['setId'],$set['components'],$set['quantity']);$signature=hash('sha256',json_encode([$resolved['setId'],array_map(static fn($i)=>[$i['productId'],$i['perSetQuantity']],$resolved['items'])]));if(isset($seenSets[$signature]))throw new NodenoControlHttpError(422,'duplicate_set');$seenSets[$signature]=true;foreach($resolved['items'] as $i)$add((string)$i['productId'],$i['quantity']);$prepared[]=['kind'=>'configured_set']+$resolved;}
 if(array_sum($quantities)>10000000)throw new NodenoControlHttpError(422,'quantity_too_large');
 $projection=nodenoWholesaleProjection($db,$catalog);$settings=array_column($projection['products'],null,'productId');$prices=[];
 foreach($quantities as $key=>$quantity){$id=(string)$key;$s=$settings[$id]??[];if($s&&empty($s['enabled']))throw new NodenoControlHttpError(422,'wholesale_unavailable');if($quantity<($s['minimumQuantity']??1))throw new NodenoControlHttpError(422,'minimum_quantity');$price=null;for($i=1;$i<=3;$i++)if(isset($s['tier'.$i.'Units'],$s['tier'.$i.'PriceMinor'])&&$quantity>=$s['tier'.$i.'Units'])$price=$s['tier'.$i.'PriceMinor'];$prices[$id]=['unitPriceMinor'=>$price,'currency'=>$price!==null?$s['currency']:null];}
 $snapshot=static function(string $id,int $quantity,?int $perSet=null)use($byId,$prices):array{$p=$byId[$id];$price=$prices[$id];return ['productId'=>$id,'code'=>$p['code'],'name'=>$p['modelName']??$p['name'],'color'=>$p['variantColor']??[],'saleUnit'=>$p['saleUnit']??'piece','quantity'=>$quantity,'units'=>$quantity,'perSetQuantity'=>$perSet,'unitPriceMinor'=>$price['unitPriceMinor'],'lineTotalMinor'=>$price['unitPriceMinor']!==null?$price['unitPriceMinor']*$quantity:null,'currency'=>$price['currency']];};
 $lines=[];
 foreach($prepared as $line){if($line['kind']==='product'){$lines[]=$line+$snapshot($line['productId'],$line['quantity']);continue;}$components=[];$total=0;$known=true;$currencies=[];$units=0;foreach($line['items'] as $i){$c=$snapshot($i['productId'],$i['quantity'],$i['perSetQuantity']);$components[]=$c;$units+=$c['quantity'];if($c['lineTotalMinor']===null)$known=false;else{$total+=$c['lineTotalMinor'];$currencies[$c['currency']]=true;}}$singleCurrency=$known&&count($currencies)===1;$lines[]=['kind'=>'configured_set','setId'=>$line['setId'],'productId'=>null,'code'=>null,'name'=>$line['name'],'color'=>[],'unit'=>'set','quantity'=>$line['quantity'],'units'=>$units,'components'=>$components,'unitPriceMinor'=>$singleCurrency?intdiv($total,$line['quantity']):null,'lineTotalMinor'=>$singleCurrency?$total:null,'currency'=>$singleCurrency?array_key_first($currencies):null];}
 return $lines;
}
function nodenoWholesaleLineSummary(array $line):string {
 $name=$line['name']['tr']??$line['code']??'';$unit=$line['unit']==='set'?'takım':'adet';$result=$name.' · '.$line['quantity'].' '.$unit;
 if($line['kind']==='configured_set')foreach($line['components'] as $c)$result.="\n  ".($c['name']['tr']??$c['code']).' · her takımda '.$c['perSetQuantity'].' · toplam '.$c['quantity'].' '.($c['saleUnit']==='set'?'takım':'adet').' · '.($c['color']['tr']??'');
 return $result."\n".($line['lineTotalMinor']===null?'Fiyat: teklif ile':number_format($line['lineTotalMinor']/100,2,'.','').' '.$line['currency']);
}
